// #6e5ece (6a993d666cd36172db6e5ece) — экран звонка: завершение только клавиатурой (AC5/AC7). Кейс CALL-018.
// @call — ТРАТИТ кредиты OpenAI (официальный звонок ~10 с). Обычный регресс без звонков: npm test -- --grep-invert @call.
// НЕ prod-safe: создаёт кандидата «QA-AUTO-A11Y-CALL-…» (link_only) и использует его единственную официальную попытку;
// кандидат не удаляется (правило проекта). Путь до звонка — мышью (его клавиатуру проверяет CALL-015), звонок — только клавиши.
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import { createCandidateLink, launchCandidate, goToPractice, goToOfficialConfirm } from './support';
import { focused, tabTo } from './a11y-support';

const HASH = '#6a993d666cd36172db6e5ece';

test.describe(`Экран звонка — завершение клавиатурой (${HASH})`, () => {
  test(`официальный звонок: Tab → «?» и «לסיים שיחה» с видимой обводкой; Enter → «לאשר סיום שיחה» + «השיחה הרשמית לא תתחדש אחרי הסיום.», фокус на ней; Enter → «הסימולציה הושלמה» @desktop @data @call ${HASH}`, async ({ asUser }) => {
    test.setTimeout(6 * 60_000);
    const business = await asUser('business');
    const name = `QA-AUTO-A11Y-CALL-${runStamp()}`;
    const link = await createCandidateLink(business, name);
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}»: официальная попытка использована (завершена кандидатом), не удаляется` });

    const cand = await launchCandidate({ width: 1440, height: 900 });
    try {
      const { page, counts } = cand;
      await goToPractice(page, link);
      await goToOfficialConfirm(page);

      // Старт тоже с клавиатуры: фокус на «מוכן, מתחילים» → Enter.
      await page.getByRole('button', { name: 'מוכן, מתחילים' }).focus();
      await page.keyboard.press('Enter');
      await expect(page.getByText('הניסיון הרשמי').first()).toBeVisible({ timeout: 30_000 });
      // Соединение: таймер role=timer и статус «מחובר · הלקוח מקשיב» / «הלקוח מדבר» (факт 15.10).
      await expect(page.getByRole('timer')).toBeVisible({ timeout: 60_000 });
      await expect(page.getByRole('status').filter({ hasText: /מחובר|הלקוח מדבר/ })).toBeVisible({ timeout: 30_000 });
      expect(counts.voice, 'start-voice-session').toBe(1);

      // Источник: AC5 «סדר המעבר הגיוני ומיקוד המקלדת נראה לעין»; факт 15.10: на экране звонка две остановки — «?» и «לסיים שיחה».
      const stops = await tabTo(page, /^לסיים שיחה$/, 6);
      expect(stops.some((s) => /פנייה לגורם אנושי/.test(s)), `«?» не в порядке Tab: ${stops.join(' → ')}`).toBe(true);

      // Источник: AC7 «כל פעולה ניתנת לביצוע במקלדת בלבד» — окончание и подтверждение клавишей Enter.
      await page.keyboard.press('Enter');
      const confirm = page.getByRole('button', { name: 'לאשר סיום שיחה' });
      await expect(confirm).toBeVisible();
      await expect(page.getByText('השיחה הרשמית לא תתחדש אחרי הסיום.')).toBeVisible();
      await expect(confirm).toBeFocused();
      expect((await focused(page)).visibleRing, 'обводка на «לאשר סיום שיחה»').toBe(true);

      const ended = page.waitForResponse(
        (r) => r.url().includes('/functions/v1/end-candidate-attempt') && r.request().method() === 'POST',
        { timeout: 60_000 },
      );
      await page.keyboard.press('Enter');
      expect((await ended).ok(), 'end-candidate-attempt').toBe(true);
      await expect(page.getByText('הסימולציה הושלמה').first()).toBeVisible({ timeout: 60_000 });
      // После окончания фокус не теряется в исчезнувшей кнопке: Tab доходит до «?».
      await tabTo(page, /פנייה לגורם אנושי/, 4);
      expect(counts.voice, 'второй старт звонка').toBe(1);
    } finally {
      await cand.browser.close();
    }
  });
});
